/* map q14 (122 mục) — engine-API đợt 1391-1400 Ch.1400 */
window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q14"]=window.__LIBQ["the-gioi-hoan-my"]["q14"]||{};window.__LIBQ["the-gioi-hoan-my"]["q14"]["map"]={"updatedAt":"2026-07-26","count":122,"nodes":[{"id":"noi-sau-trong-dai-vu-tru","name":"Nơi sâu trong đại vũ trụ","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực sâu trong vũ trụ nơi Bình Loạn Quyết va chạm với cửu chuyển quyền ấn.","detail":"Nguyên Thần kiếm thai của Vương Trường Sinh và quyền ấn hợp nhất của Mạnh Thiên Chính va chạm tại đây, khiến một chòm sao bùng nổ và cả vùng vũ trụ rạn nứt rồi tối tắt.","theLucLienQuan":["Vương gia"],"nguon":["@c1301"]},{"id":"vuong-gia-tien-duoc-vien","name":"Vương gia tiên dược viên","cn":"","capDo":"khac","parentId":"dai-ban-doanh-vuong-gia","blurb":"Dược viên đặc biệt của Vương gia, nơi Tử Phủ thảo sinh trưởng trên những tảng đá tím.","detail":"Khu vực không có đất hay thảm thực vật thông thường nhưng nuôi được bảy, tám cây Tử Phủ thảo. Những tảng đá tím được truyền là mảnh vỡ Tử Phủ của cao thủ tiên gia.","theLucLienQuan":["Vương gia"],"nguon":["@c1302"]},{"id":"truong-sinh-vuon-thuoc-cua-vuong-gia","name":"Trường Sinh vườn thuốc của Vương gia","cn":"","capDo":"khac","parentId":"dai-ban-doanh-vuong-gia","blurb":"Mật thổ nằm giữa các thần dược viên của Vương gia, dùng để bồi dưỡng một đoạn rễ Trường Sinh dược.","detail":"Đây là cấm địa mà chỉ Vương Trường Sinh được đặt chân vào. Đoạn rễ Trường Sinh dược bên trong được tưới bằng thần tuyền và linh dịch từ thời Thái cổ.","theLucLienQuan":["Vương gia"],"nguon":["@c1302"]},{"id":"vuong-gia-to-dien","name":"Vương gia tổ điện","cn":"","capDo":"khac","parentId":"dai-ban-doanh-vuong-gia","blurb":"Tổ điện của Vương gia, nơi gia chủ viết pháp chỉ hòa giải với Thạch Hạo.","detail":"Huyền tôn của Vương Đại công khai chống đối tại đây rồi bị Mạnh Thiên Chính giết sau khi Vương Đại không thể ngăn cản.","theLucLienQuan":["Vương gia"],"nguon":["@c1302"]},{"id":"truong-sinh-co-dia","name":"Trường Sinh cổ địa","cn":"","capDo":"khac","parentId":"vo-luong-thien","blurb":"Địa vực nơi Vương gia tọa lạc.","detail":"Mạnh Thiên Chính và Thạch Hạo rời Trường Sinh cổ địa sau khi lấy được pháp chỉ hòa giải từ Vương gia.","theLucLienQuan":["Vương gia"],"nguon":["@c1302"]},{"id":"vuc-ngoai-bien-cuong","name":"Vực ngoại biên cương","cn":"","capDo":"vuc","parentId":"vuc-ngoai","blurb":"Khu vực biên cương tiếp giáp thế giới bên kia.","detail":"Một tòa hùng quan bị phong ấn từ lâu tại đây bất ngờ rạn nứt rồi sụp đổ, trong khi các cự tộc của Cửu Thiên Thập Địa chưa biết biến cố đã xảy ra.","theLucLienQuan":["Cửu Thiên Thập Địa"],"nguon":["@c1302"]},{"id":"hung-quan-bien-cuong","name":"Hùng quan biên cương","cn":"","capDo":"khac","parentId":"vuc-ngoai-bien-cuong","blurb":"Tòa hùng quan cổ xưa nằm tại nơi tiếp giáp thế giới bên kia.","detail":"Công trình đã bị phong ấn trong một thời gian không rõ dài bao lâu. Nó đột ngột rạn nứt, phát ra tiếng vang lớn rồi sụp đổ hoàn toàn.","theLucLienQuan":["Cửu Thiên Thập Địa"],"nguon":["@c1302","@c1303"],"aliases":["Biên cương","Biên Hoang hùng quan"]},{"id":"dong-phu-chan-tien-co-dai","name":"Động phủ Chân Tiên cổ đại","cn":"","aliases":["Tiên gia đạo trường"],"capDo":"khac","parentId":"cuu-thien","blurb":"Những động phủ và đạo trường do Chân Tiên cổ đại để lại. Mạnh Thiên Chính đề xuất khai quật rồi di chuyển chúng lại gần nhau để tạo căn cơ chung cho ba viện.","detail":"Các động phủ chứa trận văn khủng bố nên việc di chuyển vô cùng khó khăn. Kế hoạch dự kiến hợp nhất nhiều nơi thành một bảo địa cho Tiên Viện, Thánh Viện và Thiên Thần Thư Viện.","theLucLienQuan":["Thiên Thần Thư Viện","Tiên Viện","Thánh Viện"],"nguon":["@c1303"]},{"id":"dai-xich-thien","name":"Đại Xích Thiên","cn":"","aliases":["Ly Hận Thiên"],"capDo":"vuc","parentId":"cuu-thien","blurb":"Một trong cửu thiên, có vùng biên cương và cổ quan từng được coi là không thể phá vỡ. Cuộc tập kích bất ngờ biến khu vực biên giới thành quỷ vực.","detail":"Cổ quan tại biên cương Đại Xích Thiên bị Luyện Tiên Hồ phá hủy, sau đó một bàn tay đen quét sạch sinh linh trong vùng. Biến cố này mở đầu cuộc chiến sớm hơn hàng nghìn năm so với suy tính của các cường giả.","theLucLienQuan":["Dị vực"],"nguon":["@c1304"]},{"id":"co-thanh-bien-cuong-dai-xich-thien","name":"Cổ thành biên cương Đại Xích Thiên","cn":"","aliases":[],"capDo":"thanh","parentId":"dai-xich-thien","blurb":"Hùng quan trấn giữ thông đạo tại biên cương Đại Xích Thiên, được xây bằng tiên cốt và huyết nhục tiên dân. Thành trì đột ngột nứt vỡ rồi bị Luyện Tiên Hồ phá hủy.","detail":"Cổ thành vốn được xem là kiên cố tuyệt đối nhưng rạn nứt dưới ánh bình minh và nhanh chóng nổ tung. Toàn bộ tu sĩ bên trong bị nghiền nát, còn Tiên Thiên tinh huyết của họ bị Luyện Tiên Hồ hút sạch.","theLucLienQuan":["Dị vực"],"nguon":["@c1304"]},{"id":"ba-ngan-chau-bien-hoang","name":"Ba ngàn châu biên hoang","cn":"","aliases":[],"capDo":"khac","parentId":"ba-ngan-chau","blurb":"Khu vực biên hoang của Ba ngàn châu từng được nhận định là điểm yếu nhất và có khả năng bị Dị vực đột nhập cao nhất.","detail":"Nhiều thế hệ chí cường giả đã tới cổ thành tại khu vực này trấn thủ vì cho rằng đây sẽ là hướng tấn công nguy hiểm. Tuy nhiên, cuộc tập kích mở màn lại xảy ra tại Đại Xích Thiên.","theLucLienQuan":["Dị vực"],"nguon":["@c1304"]},{"id":"bach-cot-son","name":"Bạch Cốt Sơn","cn":"","capDo":"khac","parentId":null,"blurb":"Một mật địa bạch cốt mà người ngoài rất khó tiến vào, đồng thời là địa bàn của cường tộc Bạch Cốt Sơn.","detail":"Bạch cốt trải khắp nơi trong mật địa này. Có lời truyền rằng các sinh linh sinh sống tại đây đều do cốt thần biến thành.","theLucLienQuan":["Bạch Cốt Sơn"],"nguon":["@c1305"]},{"id":"nguyen-thuy-co-gioi","name":"Nguyên Thủy Cổ Giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Thế giới cổ từng bao gồm nhiều khu vực rộng lớn, trong đó có Đại Xích Thiên.","detail":"Nguyên Thủy Cổ Giới bị đánh vỡ sau trận chiến cuối thời Tiên Cổ, để lại những vùng trời thuộc cửu thiên thập địa.","theLucLienQuan":[],"nguon":["@c1306"]},{"id":"bien-cuong-dai-xich-thien","name":"Biên cương Đại Xích Thiên","cn":"","capDo":"vuc","parentId":"dai-xich-thien","blurb":"Khu vực cuối Đại Xích Thiên tiếp giáp Hỗn Độn và khe nứt dẫn sang đại thế giới của dị vực.","detail":"Nhiều thành trì và bộ lạc tại đây đã bị hủy diệt, hàng trăm triệu sinh linh không còn người sống sót. Sinh hồn chưa tan cùng quỷ khí khiến toàn vùng mang cảnh tượng như địa ngục.","theLucLienQuan":["Dị vực"],"nguon":["@c1306"]},{"id":"chan-long-sao-huyet","name":"Chân Long sào huyệt","cn":"","capDo":"khac","parentId":"dai-xich-thien","blurb":"Cổ động trước một ngọn núi lớn, từng là nơi Chân Long xây tổ và ấp trứng.","detail":"Chân Long từng dùng tinh hạch dựng tổ và dẫn Hỗn Độn khí vào ấp trứng tại đây, nhưng sào huyệt đã bị bỏ hoang từ lâu.","theLucLienQuan":[],"nguon":["@c1306"]},{"id":"hoa-diem-nham-tuong-bien-kim-o","name":"Hỏa diễm nham tương biển Kim Ô","cn":"","capDo":"khac","parentId":"dai-xich-thien","blurb":"Biển dung nham vô tận hình thành quanh thi thể Kim Ô khổng lồ.","detail":"Thi thể Kim Ô vẫn còn phát sáng và thiêu đốt vùng núi xung quanh, biến nơi này thành một biển hỏa diễm và nham tương.","theLucLienQuan":[],"nguon":["@c1306"]},{"id":"phe-tich-hung-quan","name":"Phế tích hùng quan","cn":"","capDo":"khac","parentId":"bien-cuong-dai-xich-thien","blurb":"Tàn tích của một hùng quan đã sụp đổ tại biên cương Đại Xích Thiên.","detail":"Bên dưới phế tích có vực sâu và thông đạo màu đen. Sinh linh Bất Hủ dị vực phát lời uy hiếp và vươn bàn tay đen qua khu vực này để công kích quân vạn tộc.","theLucLienQuan":["Dị vực"],"nguon":["@c1307"]},{"id":"thong-dao-mau-den","name":"Thông đạo màu đen","cn":"","capDo":"khac","parentId":"phe-tich-hung-quan","blurb":"Lối đi nằm trong vực sâu dưới phế tích hùng quan, nối về phía dị vực.","detail":"Tiếng nói và bàn tay đen của sinh linh Bất Hủ vươn sang qua thông đạo này. Việc vượt qua vẫn bị giới hạn bởi khoảng cách, giới bích và sự bài xích của quy tắc thiên địa.","theLucLienQuan":["Dị vực"],"nguon":["@c1307"]},{"id":"vuc-ngoai","name":"Vực Ngoại","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực ngoài thiên địa chịu ảnh hưởng dữ dội từ trận giao chiến giữa Mạnh Thiên Chính và sinh linh Bất Hủ.","detail":"Bão năng lượng và quy tắc sinh ra từ va chạm giữa Tổ Long giác với bàn tay đen quét qua Vực Ngoại, khiến nhiều đại tinh rơi xuống hoặc nổ tung.","theLucLienQuan":["Thiên Thần Thư Viện","Dị Vực"],"nguon":["@c1308"]},{"id":"the-gioi-di-vuc","name":"Dị Vực","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Thế giới của các sinh linh Bất Hủ đang tìm cách tiến công Đại Xích Thiên qua giới bích.","detail":"Dị Vực mới liên kết một phần với Đại Xích Thiên, vì vậy sinh linh Bất Hủ chưa thể hoàn toàn vượt giới mà chỉ vươn bàn tay đen sang chiến trường.","theLucLienQuan":["Dị Vực"],"nguon":["@c1308"]},{"id":"vuc-sau-mau-den","name":"Vực sâu màu đen","cn":"","capDo":"khac","parentId":"dai-xich-thien","blurb":"Thông đạo giáp giữa hai giới tại Đại Xích Thiên. Bàn tay lớn màu đen rút về đây và một nhóm sinh linh dị vực đã từ đó vượt sang.","detail":"Vực sâu phun ra khói đen khi nhóm hậu bối dị vực vượt giới. Khu vực phụ cận cho phép những sinh linh chưa đạt lĩnh vực bất hủ tránh phần nào sự áp chế của thiên địa Cửu Thiên Thập Địa.","theLucLienQuan":["Dị vực","Cửu Thiên Thập Địa"],"nguon":["@c1309"]},{"id":"cam-dia-sinh-menh-cua-cuu-thien","name":"Cấm địa sinh mệnh của Cửu Thiên","cn":"","capDo":"khac","parentId":"cuu-thien","blurb":"Một cấm địa sinh mệnh tại Cửu Thiên, nơi Sở Sơn Hà cùng bảy Vương giả trẻ tuổi từng tiến vào tìm binh khí Tiên Vương và thăm dò một truyền thuyết.","detail":"Trong tám thiên tài tiến vào cấm địa, chỉ Sở Sơn Hà sống sót trở về. Ông mang theo bệnh căn liên quan đến Hắc Bạch Sinh Tử Quang, còn bảy người khác đều không trở lại.","theLucLienQuan":["Tiên Viện","Cửu Thiên Thập Địa"],"nguon":["@c1310"]},{"id":"hac-am-tham-uyen","name":"Hắc Ám Thâm Uyên","cn":"","capDo":"khac","parentId":null,"blurb":"Vực sâu ngăn cách hai phía của chiến trường giữa hai giới.","detail":"Hơn mười cường giả trẻ tuổi dị vực từ bên bờ Hắc Ám Thâm Uyên tiến tới sau khi phát hiện các tiên chủng quý hiếm của đối phương.","theLucLienQuan":["Dị vực","Cửu thiên thập địa"],"nguon":["@c1311"]},{"id":"phe-tich-phu-can-vuc-sau-mau-den","name":"Phế tích phụ cận vực sâu màu đen","cn":"","capDo":"khac","parentId":"hac-am-tham-uyen","blurb":"Khu phế tích nằm gần vực sâu màu đen, nơi cường giả trẻ tuổi hai bên đồng loạt xuất trận.","detail":"Mặt đất tại đây nứt vỡ dưới bước chân các sinh linh dị vực; cát đá cuốn lên khi nhiều cuộc giao chiến cùng lúc bùng nổ.","theLucLienQuan":["Dị vực","Cửu Thiên Thập Địa"],"nguon":["@c1312"]},{"id":"chien-truong-hai-gioi","name":"Chiến trường hai giới","cn":"","capDo":"khac","parentId":"bien-cuong-dai-xich-thien","blurb":"Chiến trường nơi các kỳ tài trẻ tuổi Cửu Thiên Thập Địa và dị vực tiến hành những trận tử chiến.","detail":"Tiên Quy Giáp Phiến chọn Xà Dạ Xoa và Huyền Côn làm cặp đối thủ đầu tiên tại đây. Huyền Côn bị giết sau hơn một trăm hiệp, còn Xà Dạ Xoa giữ quyền tiếp tục giao chiến.","theLucLienQuan":["Cửu Thiên Thập Địa","Dị vực"],"nguon":["@c1314"]},{"id":"co-chien-truong","name":"Cổ chiến trường","cn":"","capDo":"khac","parentId":null,"blurb":"Chiến trường cổ khô lạnh nơi các vương giả trẻ tuổi của hai giới tiến hành những trận quyết đấu sinh tử.","detail":"Lữ Hồng và Hoàng Kim Ma Điểu tử chiến tại đây suốt khoảng chín trăm hiệp. Không gian chiến trường chịu sự giằng co và giám sát của các cường giả Cửu Thiên Thập Địa cùng Dị vực.","theLucLienQuan":["Cửu Thiên Thập Địa","Dị vực"],"nguon":["@c1315"]},{"id":"chien-truong-bien-cuong-dai-xich-thien","name":"Chiến trường biên cương Đại Xích Thiên","cn":"","capDo":"khac","parentId":"bien-cuong-dai-xich-thien","blurb":"Chiến trường nơi tuổi trẻ hai giới tiến hành các trận quyết đấu do Tiên Quy Giáp Phiến lựa chọn.","detail":"Tại đây, cửu thiên thập địa liên tiếp mất bốn tuổi trẻ anh kiệt. Trong chương này, thiên tài Thánh Viện và Tử Nhật Thiên Quân lần lượt bị Ngân Linh cùng Đường Ngô giết chết.","theLucLienQuan":["Dị vực","Thánh Viện","Tiên Viện"],"nguon":["@c1316"]},{"id":"ky-long-co-son-mach","name":"Kỳ Long Cổ Sơn Mạch","cn":"","capDo":"vuc","parentId":"the-gioi-di-vuc","blurb":"Sơn mạch thuộc Dị vực, gắn với Bạch Ngân Vương tộc.","detail":"Ngân Linh công khai mình là thành viên Bạch Ngân Vương tộc tại Kỳ Long Cổ Sơn Mạch sau khi giết thiên tài Thánh Viện.","theLucLienQuan":["Bạch Ngân Vương tộc"],"nguon":["@c1316"]},{"id":"co-dia-an-lan","name":"Cổ địa An Lan","cn":"","capDo":"khac","parentId":"di-vuc","blurb":"Cổ địa của An Lan tộc tại Dị vực.","detail":"Địa bàn của dòng họ An Lan, được nói là đã rất lâu không có người trẻ tuổi bước ra.","theLucLienQuan":["An Lan tộc"],"nguon":["@c1320"]},{"id":"chien-truong-truoc-vuc-sau-hac-am","name":"Chiến trường trước vực sâu hắc ám","cn":"","capDo":"khac","parentId":"hac-am-tham-uyen","blurb":"Chiến trường nơi hai phe Cửu Thiên Thập Địa và Dị Vực chứng kiến chuỗi giao chiến của Thạch Hạo với các Vương giả trẻ tuổi.","detail":"Tại đây, Thạch Hạo công khai ăn chiến lợi phẩm từ ba Vương giả Dị Vực, giao chiến và đánh chết Hỏa Nham Vương, sau đó thách đấu đồng thời Xà Dạ Xoa cùng Hoàng Kim Ma Điểu.","theLucLienQuan":["Cửu Thiên Thập Địa","Dị Vực"],"nguon":["@c1323"]},{"id":"bien-dung-nham-tren-chien-truong","name":"Biển dung nham trên chiến trường","cn":"","capDo":"khac","parentId":"chien-truong-truoc-vuc-sau-hac-am","blurb":"Vùng dung nham được Hỏa Nham Vương tạo ra khi nung chảy đại địa trong trận đấu với Thạch Hạo.","detail":"Dung nham dâng lên như đại dương đỏ, mang nhiệt độ đủ làm hư không sụp đổ và giúp Hỏa Nham Vương che giấu chân thân. Thạch Hạo dùng động thiên cùng lôi đình áp chế khu vực này và buộc đối thủ hiện hình.","theLucLienQuan":["Hỏa nham Vương tộc","Dị Vực"],"nguon":["@c1323"]},{"id":"gioi-bich-giua-hai-gioi","name":"Giới bích giữa hai giới","cn":"","capDo":"khac","parentId":null,"blurb":"Ranh giới quy tắc ngăn cường giả Dị vực tiến sâu vào Cửu Thiên Thập Địa tại biên cương Đại Xích Thiên.","detail":"Sắc Đức vừa định vượt lên tấn công Thạch Hạo đã bị lực lượng giới bích áp chế và quy tắc phản phệ. Cường giả càng mạnh càng chịu sự áp chế rõ rệt khi cố vượt qua ranh giới này.","theLucLienQuan":["Dị vực","Cửu Thiên Thập Địa"],"nguon":["@c1326"]},{"id":"bat-diet-phong","name":"Bất Diệt Phong","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm được nhắc đến trong sự kiện cuối thời Tiên cổ liên quan đến Hạc Vô Song và Luyện Tiên Hồ.","detail":"Hạc Vô Song từng xuất hiện cùng Luyện Tiên Hồ ở khu vực gần Bất Diệt Phong để thu lấy tinh huyết của cường giả.","theLucLienQuan":["Hạc gia"],"nguon":["@c1329"]},{"id":"dai-xich-thien-bien-cuong","name":"Đại Xích Thiên biên cương","cn":"","capDo":"vuc","parentId":"dai-xich-thien","blurb":"Chiến trường nằm ở biên cương Đại Xích Thiên, đồng thời là một mục tiêu quan trọng trong cuộc tiến công kép của Dị vực.","detail":"Thành trì tại đây được xây bằng tiên cốt nhưng người kiến tạo không rõ danh tính, bởi tiên dân thời đó đã bị giết sạch. Nơi này che giấu bí mật liên quan đến việc Dị vực từng san bằng Cửu Thiên Thập Địa rồi đột ngột rút quân, khiến cuộc tấn công hiện tại không chỉ là nghi binh.","theLucLienQuan":["Dị vực","Cửu Thiên Thập Địa"],"nguon":["@c1331"]},{"id":"phong-an-co-gioi-trong-hon-don","name":"Phong ấn cổ giới trong hỗn độn","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Một cổ giới bị phong ấn trong hỗn độn, có tiết điểm được An Lan và Du Đà suy tính từ trước.","detail":"Lạc Ma dùng nhãn cầu, máu bất hủ và phần tàn hồn cuối cùng hóa thành dấu ấn tọa độ xuyên thủng hỗn độn, nhằm cưỡng ép mở tiết điểm của cổ giới này.","theLucLienQuan":["Dị vực"],"nguon":["@c1333","@c1336"]},{"id":"hac-am-vuc-sau","name":"Hắc ám vực sâu","cn":"","capDo":"khac","parentId":"co-chien-truong","blurb":"Vực sâu âm u nằm cạnh tế đàn triệu hồn trong cổ chiến trường Đại Xích Thiên.","detail":"Vô số quỷ ảnh và anh linh hội tụ quanh vực sâu khi các lão nhân Dị vực tụng chiêu hồn kinh. Đoàn hồn hỏa chứa tàn hồn Lạc Ma được tám anh linh hộ tống từ đây trở về tế đàn.","theLucLienQuan":["Dị vực"],"nguon":["@c1333"]},{"id":"cu-bi-mau-den","name":"Cự bi màu đen","cn":"","capDo":"khac","parentId":"phong-an-co-gioi-trong-hon-don","blurb":"Bia đá màu đen cao mười vạn trượng, đẫm máu và trấn áp cổ giới bị che giấu trong hỗn độn.","detail":"Cự bi cản đường chiến huyết Lạc Ma và chịu nhiều đợt công kích từ pháp ấn cùng binh khí do chân huyết biến thành. Sau khi ngũ sắc chân huyết tiêu tan, thân bia xuất hiện một khe nứt kéo dài xuống dưới và chảy ra rất nhiều máu.","theLucLienQuan":["Dị vực"],"nguon":["@c1334","@c1336"]},{"id":"cua-vao-co-gioi","name":"Cửa vào cổ giới","cn":"","capDo":"khac","parentId":"phong-an-co-gioi-trong-hon-don","blurb":"Lối vào cổ giới phong ấn, nơi Tiên huyết tràn ngập và huyết linh chặn đường.","detail":"Khu vực chứa Tiên huyết chưa luyện hóa, nhiều sinh linh do máu hóa thành và các Tiên khí tàn khuyết. Sát lực cùng chiến ý còn sót lại khiến cả đoàn Dị vực lẫn đoàn Cửu Thiên chưa thể vượt qua.","theLucLienQuan":["Đoàn dị vực tại cổ giới phong ấn","Đoàn Cửu Thiên của Mạnh Thiên Chính"],"nguon":["@c1336"]},{"id":"co-gioi-chua-chien-truong-tien-co","name":"Cổ giới chứa chiến trường Tiên cổ","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Cổ giới có vùng núi mang khí tức gần với tiên khí, sông Linh dịch và nhiều thảo dược quý, nhưng nơi sâu hơn lại là một tử địa rộng lớn.","detail":"Sau khoảng tám nghìn dặm, cảnh tượng trù phú chuyển thành chiến trường khô cằn kéo dài hàng trăm nghìn dặm. Nơi đây từng bị pháp tắc Tiên đạo quét qua và còn lưu lại nhiều loại cổ huyết, binh khí tàn tạ cùng dấu tích của các sinh linh khổng lồ.","theLucLienQuan":["Dị vực","Cửu Thiên Thập Địa","Người bảo vệ một mạch"],"nguon":["@c1337"]},{"id":"mo-tien-gan-loi-vao-co-gioi","name":"Mộ tiên gần lối vào cổ giới","cn":"","capDo":"khac","parentId":"co-gioi-chua-chien-truong-tien-co","blurb":"Vài ngôi mộ lớn có bia sắt nằm gần lối vào cổ giới, mang uy thế đủ phá hủy pháp khí đào mộ.","detail":"Các ngôi mộ tự cuốn Tiên huyết và binh khí tàn tạ ở khu vực lân cận trở lại bên trong. Khi một sinh linh Dị vực thử khai quật, pháp khí của hắn lập tức vỡ thành nhiều mảnh, khiến hai phe tạm bỏ ý định thăm dò mộ.","theLucLienQuan":["Dị vực","Cửu Thiên Thập Địa"],"nguon":["@c1337"]},{"id":"chien-truong-cua-lac-ma","name":"Chiến trường của Lạc Ma","cn":"","capDo":"khac","parentId":"co-gioi-chua-chien-truong-tien-co","blurb":"Tử địa lưu lại máu ngũ sắc của Lạc Ma, máu người bảo vệ và hỗn độn huyết của một đối thủ cổ xưa.","detail":"Chiến trường có vô số tinh thể mang dấu tay khổng lồ, được suy đoán là đã bị một sinh linh sắp chết kéo khỏi vũ trụ. Những loại huyết dịch còn sót lại cho thấy nơi đây từng diễn ra một trận chiến cấp Tiên đạo giữa Lạc Ma, một tộc nhân người bảo vệ và sinh linh mang hỗn độn huyết.","theLucLienQuan":["Dị vực","Người bảo vệ một mạch"],"nguon":["@c1337"]},{"id":"ban-dau-nhat-noi","name":"Ban đầu nhất nơi","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi xuất thân của vị tộc nhân người bảo vệ đã để lại máu trên chiến trường cổ.","detail":"Thông tin được lưu trong huyết dịch xác nhận vị tộc nhân này không thuộc thế giới hiện tại mà đến từ ban đầu nhất nơi. Vị trí và bản chất cụ thể của địa điểm chưa được làm rõ.","theLucLienQuan":["Người bảo vệ một mạch"],"nguon":["@c1337"]},{"id":"dai-dia-sau-chien-truong","name":"Đại địa sau chiến trường","cn":"","capDo":"khac","parentId":"chien-truong-co","blurb":"Vùng đại địa xuất hiện sau khi đoàn người vượt qua khoảng năm trăm nghìn dặm chiến trường lần thứ hai. Nơi đây có tiên sơn, thác thần và đảo lơ lửng nhưng hoàn toàn không thấy sinh vật sống.","detail":"Mặt đất đỏ sậm do máu của Chí Cường giả nhuộm thành, trong khi linh thảo và lão dược mọc khắp nơi. Tiên khí vẫn tỏa ra từ những hòn đảo ngang trời và các cảnh quan thần dị.","theLucLienQuan":["Dị vực","Đoàn Cửu Thiên của Mạnh Thiên Chính"],"nguon":["@c1338"]},{"id":"tien-cung-co","name":"Tiên cung cổ","cn":"","capDo":"khac","parentId":"dai-dia-sau-chien-truong","blurb":"Quần thể cung điện cổ nằm giữa sơn mạch cao bảy tám vạn trượng. Trải qua một kỷ nguyên, kiến trúc vẫn chưa hủ diệt và còn lưu chuyển khí tức Tiên Đạo.","detail":"Tại phế tích các cự cung trong khu vực này, đoàn người phát hiện một bộ xương trắng đang gảy đàn cổ và một Phượng Hoàng đỏ thắm chưa thành niên đang nhìn chằm chằm họ.","theLucLienQuan":["Dị vực","Đoàn Cửu Thiên của Mạnh Thiên Chính"],"nguon":["@c1338"]},{"id":"co-kien-truc-quan","name":"Cổ kiến trúc quần","cn":"","capDo":"khac","parentId":"phong-an-co-gioi-trong-hon-don","blurb":"Quần thể cung điện cổ trong cổ giới, nơi thi thể Phượng Hoàng trưởng thành bay lên.","detail":"Các kiến trúc bị cuộc giao phong giữa nhiều pháp khí làm sụp đổ, qua đó để lộ tế đàn trung tâm trên núi lớn.","theLucLienQuan":["Bộ tộc Phượng Hoàng"],"nguon":["@c1339"]},{"id":"te-dan-trung-tam-tren-nui-lon","name":"Tế đàn trung tâm trên núi lớn","cn":"","capDo":"khac","parentId":"phong-an-co-gioi-trong-hon-don","blurb":"Tế đàn nằm trên núi lớn tại trung tâm quần thể kiến trúc cổ, lộ ra sau khi các cung điện sụp đổ.","detail":"Trên tế đàn đặt Tiên mộc quan tài còn sinh cơ. Hoa văn và tinh huyết thần bí hội tụ tại đây, trong đó có huyết tinh lấy từ di thể Bất Hủ giả của Dị vực.","theLucLienQuan":["Dị vực"],"nguon":["@c1339"]},{"id":"co-chien-truong-trong-tien-dao-tan-tran","name":"Cổ chiến trường trong Tiên Đạo tàn trận","cn":"","capDo":"khac","parentId":"phong-an-co-gioi-trong-hon-don","blurb":"Cảnh cổ chiến trường hiện ra khi Tiên Đạo tàn trận cuốn tất cả người hiện diện vào bên trong.","detail":"Nơi này có vô tận hài cốt và di thể của các Chí Cường giả, tái hiện một chiến trường cổ nguy hiểm cho tới khi hai phe phá trận thoát ra.","theLucLienQuan":["Dị vực","Cửu Thiên Thập Địa"],"nguon":["@c1339"]},{"id":"te-dan-trong-mo-tien","name":"Tế đàn trong mộ tiên","cn":"","capDo":"khac","parentId":"mo-tien-dao-ac-ma","blurb":"Tế đàn đặt Tiên mộc quan tài cổ giữa khu mộ tiên.","detail":"Tiên mộc quan tài trên tế đàn có lá xanh và Tiên vụ bao quanh. Đây là nơi nữ tử tuyết y thức tỉnh, phát ra trường vực khóa Luyện Tiên Hồ cùng Tiên Vương quấn vải liệm và kéo hai phe trở lại.","theLucLienQuan":["Cửu Thiên","Dị vực"],"nguon":["@c1340"]},{"id":"vung-hu-khong-quanh-mo-tien","name":"Vùng hư không quanh mộ tiên","cn":"","capDo":"khac","parentId":"mo-tien-dao-ac-ma","blurb":"Vùng đất và không gian quanh mộ tiên được khắc những đồ án phức tạp tồn tại qua vạn cổ.","detail":"Khi cổ đại trận thức tỉnh, phù văn trong đất đai và hư không gây nhiễu các vô thượng pháp khí, khiến cả đoàn Cửu Thiên lẫn Dị vực không thể mở đường vượt không gian.","theLucLienQuan":["Cửu Thiên","Dị vực"],"nguon":["@c1340"]},{"id":"bai-da-bac-hai","name":"Bãi đá Bắc Hải","cn":"","capDo":"khac","parentId":"bac-hai","blurb":"Bãi đá tại Bắc Hải nơi Thạch Hạo được cho là đã lấy được một phần kinh văn.","detail":"Vương gia nhận tin Thạch Hạo lấy được kinh văn tại đây. Qua suy diễn của Vương Trường Sinh, họ cho rằng kinh văn ấy rất có thể là Bất Diệt Kinh.","theLucLienQuan":["Vương gia"],"nguon":["@c1343"]},{"id":"thien-giac-nghi-tien-phu-dia-diem","name":"Thiên Giác Nghĩ Tiên phủ","cn":"","capDo":"khac","parentId":"vo-luong-thien","blurb":"Tiên phủ nơi Thiên Giác Nghĩ bí mật tới điều động năm chiến binh khôi lỗi.","detail":"Sau khi nhận thấy nguy hiểm tại Thiên Thần Thư Viện, Thiên Giác Nghĩ đi dưới lòng đất tới đây để gọi viện binh. Năm chiến binh khôi lỗi cổ xưa từ Tiên phủ sau đó phá đất xuất hiện tại thư viện.","theLucLienQuan":["Thiên Giác Nghĩ Tiên phủ"],"nguon":["@c1344"]},{"id":"ha-vien-vuong-gia-gan-thien-than-thu-vien","name":"Hạ viện Vương gia gần Thiên Thần Thư Viện","cn":"","capDo":"khac","parentId":null,"blurb":"Pháo đài cổ kiêm hạ viện và cứ điểm của Vương gia nằm trong vùng núi gần Thiên Thần Thư Viện.","detail":"Địa điểm nằm giữa vùng núi có nhiều cổ thụ và gần một tòa cự thành. Đây là cứ điểm đầu tiên được mô tả trong cuộc phản kích của Thạch Hạo, sau đó bị chiến thuyền phá hủy.","theLucLienQuan":["Vương gia","Hạ viện Vương gia gần Thiên Thần Thư Viện","Thiên Thần Thư Viện"],"nguon":["@c1345"]},{"id":"dong-dien-tai-thien-than-thu-vien","name":"Đồng điện tại Thiên Thần Thư Viện","cn":"","capDo":"khac","parentId":"thien-than-thu-vien-dia-diem","blurb":"Nơi Thạch Hạo, Tiểu Thiên Giác Nghĩ và năm lão binh tập hợp khi Thiên Thần Thư Viện bị tấn công.","detail":"Từ khu vực trước đồng điện, Thạch Hạo trao Đại La kiếm thai cho thủ lĩnh lão binh để bay lên nghênh chiến Trường Sinh chiến kích.","theLucLienQuan":["Thiên Thần Thư Viện","Thiên Giác Nghĩ Tiên phủ"],"nguon":["@c1349"]},{"id":"long-dat-phu-de-thien-giac-nghi","name":"Lòng đất phủ đệ Thiên Giác Nghĩ","cn":"","capDo":"khac","parentId":"thien-giac-nghi-tien-phu-dia-diem","blurb":"Nơi cất giữ Nguyên Mẫu Đỉnh trong phủ đệ của Thiên Giác Nghĩ.","detail":"Nguyên Mẫu Đỉnh được thủ lĩnh lão binh gọi lên từ sâu dưới lòng đất, sau đó tạo vòng xoáy nhằm thu lấy Trường Sinh chiến kích.","theLucLienQuan":["Thiên Giác Nghĩ Tiên phủ"],"nguon":["@c1349"]},{"id":"long-dat-thien-than-thu-vien","name":"Lòng đất Thiên Thần Thư Viện","cn":"","capDo":"khac","parentId":"thien-than-thu-vien-dia-diem","blurb":"Khu vực phong ấn Nguyên Mẫu Đỉnh và cất giữ di vật liên quan đến Thiên Giác Nghĩ.","detail":"Từ lòng đất phát ra vòng xoáy có thể áp chế Tiên khí, nuốt thần lực và giữ pháp chỉ Vương gia. Nơi đây còn cất giấu đầu lâu lột xác của Thiên Giác Nghĩ.","theLucLienQuan":["Thiên Thần Thư Viện","Thiên Giác Nghĩ"],"nguon":["@c1350"]},{"id":"the-gioi-tien-phu-duoi-long-dat","name":"Thế giới Tiên phủ dưới lòng đất","cn":"","capDo":"gioi-nho","parentId":"long-dat-thien-than-thu-vien","blurb":"Không gian dưới Thiên Thần Thư Viện gồm chín ngọn núi, trong đó có đạo trường của Thiên Giác Nghĩ.","detail":"Thạch Hạo từng tiến vào nơi này và nâng được hình chiếu của Nguyên Mẫu Đỉnh, thành tích mà các chí tôn trẻ tuổi khác không làm được.","theLucLienQuan":["Thiên Thần Thư Viện","Thiên Giác Nghĩ"],"nguon":["@c1350"]},{"id":"dao-truong-thien-giac-nghi","name":"Đạo trường Thiên Giác Nghĩ","cn":"","capDo":"khac","parentId":"the-gioi-tien-phu-duoi-long-dat","blurb":"Một trong chín ngọn núi thuộc thế giới Tiên phủ dưới lòng đất.","detail":"Đạo trường gắn với Thiên Giác Nghĩ và là nơi cất giấu binh khí cùng di vật có quan hệ với vị Thập Hung này.","theLucLienQuan":["Thiên Giác Nghĩ"],"nguon":["@c1350"]},{"id":"dao-truong-vo-luong-thien-doan-tien-co-to-mach","name":"Đạo trường Vô Lượng Thiên","cn":"","capDo":"khac","parentId":"vo-luong-thien","blurb":"Đạo trường chung được mở trên một đoạn Tiên cổ tổ mạch bị tàn phá tại Vô Lượng Thiên.","detail":"Đây là một mảnh đạo thổ bao la có khói tím lượn lờ. Đoạn Tiên cổ tổ mạch dưới lòng đất tuy chỉ còn một phần ngắn nhưng vẫn tràn ra Tiên vụ, được các kỳ nhân phá bỏ phong ấn và dùng làm nơi bồi dưỡng thiên tài trong một năm trước khi họ lựa chọn có ra Biên Hoang hay không.","theLucLienQuan":["Tiên Viện","Thánh Viện","Thiên Thần Thư Viện"],"nguon":["@c1354"]},{"id":"cuu-thanh-ngoai-bien-hoang","name":"Cựu thành ngoài biên hoang","cn":"","capDo":"thanh","parentId":"bien-hoang","blurb":"Một cổ thành nằm ngoài Đế Thành, giữa hư vô, hỗn độn và ma thổ nhuốm máu. Thành trấn áp khu vực giữa hai giới và khiến cấp bất hủ của Dị vực kiêng kỵ.","detail":"Nguồn gốc và tình trạng thật sự của cựu thành chưa rõ, với những truyền thuyết trái ngược cho rằng đây là thành bị nguyền rủa hoặc thành trì vĩ đại bảo hộ thế giới. Thạch Hạo liên hệ nơi này với cô thành mà biên hoang thất vương cùng cư dân già trẻ từng liều chết phòng thủ.","theLucLienQuan":["Cửu Thiên Thập Địa","Dị vực"],"nguon":["@c1355"]},{"id":"de-thanh-bien-hoang","name":"Đế Thành biên hoang","cn":"","capDo":"thanh","parentId":"bien-hoang","blurb":"Tòa thành khổng lồ cao vút trong đại vũ trụ, có tường thành xây bằng tinh thần. Đây là biên quan kiên cố và khác với cựu thành nằm xa hơn bên ngoài.","detail":"Đế Thành được xem là thành trì kiên cố nhất trong lịch sử tại biên hoang, giữ vị trí phòng thủ trước Dị vực.","theLucLienQuan":["Cửu Thiên Thập Địa","Đế Thành"],"nguon":["@c1355"]},{"id":"thien-uyen","name":"Thiên Uyên","cn":"","capDo":"khac","parentId":"bien-hoang","blurb":"Một vực sâu ở ngoài biên hoang nhưng hướng ngược lên bầu trời. Độ sâu của nó vượt qua tinh vực mà vẫn chưa thấy tận cùng.","detail":"Thiên Uyên là một trong những cấu trúc thần bí đang bảo hộ Cửu Thiên Thập Địa và ngăn cách thế giới này với Dị vực. Nguồn gốc cùng cơ chế bảo hộ của nó chưa được giải thích.","theLucLienQuan":["Cửu Thiên Thập Địa","Dị vực"],"nguon":["@c1355"]},{"id":"rung-bia-ngo-dao","name":"Rừng bia ngộ đạo","cn":"","capDo":"khac","parentId":"bien-hoang","blurb":"Một mật thổ tại biên hoang gồm nhiều khu rừng bia có thể mang lại cơ duyên ngộ đạo. Nơi này đồng thời ẩn chứa hiểm nguy chết người.","detail":"Rừng bia ngộ đạo được liệt kê trong nhóm mật thổ mà thiên tài có thể tìm kiếm tạo hóa, nhưng tỷ lệ sống sót sau khi tiến vào rất thấp.","theLucLienQuan":["Cửu Thiên Thập Địa"],"nguon":["@c1355"]},{"id":"cuu-tho-tien-gia","name":"Cựu thổ tiên gia","cn":"","capDo":"khac","parentId":"bien-hoang","blurb":"Một vùng đất cổ liên quan đến tiên gia tại biên hoang. Nơi này được nhắc đến như mật thổ chứa tạo hóa lớn và nguy hiểm khó lường.","detail":"Cựu thổ tiên gia nằm trong số những khu vực mà người muốn trưởng thành tại biên hoang có thể phải thăm dò.","theLucLienQuan":["Cửu Thiên Thập Địa"],"nguon":["@c1355"]},{"id":"day-nui-than-duoc","name":"Dãy núi thần dược","cn":"","capDo":"khac","parentId":"bien-hoang","blurb":"Một khu vực rộng lớn tại biên hoang có thần dược sinh trưởng. Cơ duyên phong phú tại đây đi kèm nguy cơ tử vong rất cao.","detail":"Dãy núi thần dược thuộc hệ thống mật thổ mà các thiên tài có thể tiến vào để tìm kiếm tạo hóa và rèn luyện.","theLucLienQuan":["Cửu Thiên Thập Địa"],"nguon":["@c1355"]},{"id":"rung-thien-thu","name":"Rừng Thiên thú","cn":"","capDo":"khac","parentId":"bien-hoang","blurb":"Một hiểm địa tại biên hoang từng khiến cả đội đại quân Dị vực đi vào rồi không trở lại. Nguyên nhân vụ mất tích chưa được làm rõ.","detail":"Rừng Thiên thú vừa thuộc nhóm mật thổ chứa tạo hóa, vừa là bằng chứng cho thấy biên hoang còn những sức mạnh bí ẩn có thể gây tổn thất lớn cho Dị vực.","theLucLienQuan":["Cửu Thiên Thập Địa","Dị vực"],"nguon":["@c1355"]},{"id":"tang-vuc","name":"Táng vực","cn":"","capDo":"vuc","parentId":"bien-hoang","blurb":"Một vùng bí ẩn tại biên hoang được liệt kê cùng các mật thổ chứa tạo hóa tuyệt thế. Nơi này cũng mang đại hung hiểm đối với người xâm nhập.","detail":"Thông tin về địa thế, nguồn gốc và những tồn tại trong Táng vực chưa được tiết lộ.","theLucLienQuan":["Cửu Thiên Thập Địa"],"nguon":["@c1355"]},{"id":"hem-nui-lon-than-bi","name":"Hẻm núi lớn thần bí","cn":"","capDo":"khac","parentId":"bien-hoang","blurb":"Một hẻm núi phủ sương tại biên hoang, nơi thiên quân vạn mã của gia tộc cổ xưa Dị vực từng mất tích. Binh khí và lều trại còn nguyên nhưng toàn bộ sinh linh biến mất.","detail":"Ngay cả Dị vực cũng không tìm được lời giải rõ ràng cho vụ mất tích, cho thấy hẻm núi là một trong những hiểm địa khó dò nhất tại biên hoang.","theLucLienQuan":["Dị vực","Cửu Thiên Thập Địa"],"nguon":["@c1355"]},{"id":"tien-tho","name":"Tiên thổ","cn":"","capDo":"khac","parentId":"cuu-thien","blurb":"Tiên thổ là bảo địa tu luyện rộng lớn, có hoàn cảnh gần với thời Tiên cổ và được dành cho thế hệ trẻ Cửu Thiên.","detail":"Khu vực trung tâm của Tiên thổ có mười ngọn núi cao nằm trên một đoạn tổ mạch Tiên cổ còn sót lại, liên tục phun tiên vụ trắng. Bốn ngọn núi tốt nhất có nhánh tổ mạch kéo dài trực tiếp vào trong, được hỗn độn khí và tiên vụ bao quanh. Các tu sĩ trẻ tuổi Cửu Thiên tập trung tại đây để tu luyện, nghe giảng kinh và tìm hiểu kẻ địch dị vực.","theLucLienQuan":["Thánh Viện","Tiên Viện","Cửu Thiên"],"nguon":["@c1356"]},{"id":"tien-co-to-mach","name":"Tiên cổ tổ mạch","cn":"","capDo":"khac","parentId":null,"blurb":"Đoạn thiên địa tổ mạch còn sót lại từ kỷ nguyên trước, chứa Tiên Đạo khí tức nồng đậm.","detail":"Các tu sĩ trẻ tuổi bế quan gần một năm tại đây, mượn khí tức Tiên Đạo để rèn thân, dưỡng Nguyên Thần, cảm ngộ đại đạo và chuẩn bị cho hành trình tới Biên Hoang.","theLucLienQuan":[],"nguon":["@c1358"]},{"id":"dam-lay-do-dam","name":"Đầm lầy đỏ đậm","cn":"","capDo":"khac","parentId":"khu-khong-nguoi","blurb":"Vùng tử địa trong khu không người, bị máu của sinh linh nửa bước Chân Tiên nhuộm đỏ.","detail":"Máu tồn tại qua thời gian dài đã biến cả đầm lầy thành vùng nguy hiểm chết người. Sinh linh tùy tiện bước vào sẽ nhanh chóng hóa thành bùn mục.","theLucLienQuan":[],"nguon":["@c1359"]},{"id":"co-lo-toi-de-thanh","name":"Cổ lộ tới Đế Thành","cn":"","capDo":"khac","parentId":"khu-khong-nguoi","blurb":"Con đường cổ tương đối an toàn dẫn xuyên khu không người tới Đế Thành.","detail":"Các lão nhân dẫn đoàn thiên tài đi theo cổ lộ này để tránh những vùng hiểm địa trong khu không người và tiếp cận Đế Thành trấn thủ biên hoang.","theLucLienQuan":["Cửu Thiên"],"nguon":["@c1359"]},{"id":"ngoai-thanh-de-quan","name":"Ngoại thành Đế quan","cn":"","capDo":"thanh","parentId":"de-thanh-bien-hoang","blurb":"Lớp thành phía ngoài của Đế quan, là vùng chuyển tiếp trước khi tiến vào nội thành.","detail":"Ngoại thành là một vùng cổ địa tối tăm phủ khói đen, hài cốt, cốt phấn và một số tinh hài. Muốn tiếp tục vào nội thành, người đến phải dùng đàn tròn ghép từ các mảnh xương vàng để mở đường.","theLucLienQuan":["Quân thủ thành Đế quan"],"nguon":["@c1360"]},{"id":"noi-thanh-de-quan","name":"Nội thành Đế quan","cn":"","capDo":"thanh","parentId":"de-thanh-bien-hoang","blurb":"Không gian cốt lõi rộng lớn của Đế quan, có quy mô gần như một đại thế giới.","detail":"Nội thành có những đoạn tường do tu sĩ tọa quan lâu năm trấn thủ, chiến thú khổng lồ, đại thần tiễn thủ và nhiều đội quân. Đi sâu vào trong còn có núi hình thành từ tinh thể rơi xuống, linh sơn, thác nước cùng những vùng sinh thái rộng lớn.","theLucLienQuan":["Quân thủ thành Đế quan"],"nguon":["@c1360"]},{"id":"cam-dia-trung-tam-de-thanh","name":"Cấm địa trung tâm Đế Thành","cn":"","capDo":"khac","parentId":"noi-thanh-de-quan","blurb":"Cấm địa gần trung tâm nội thành, nơi sinh linh bình thường không được phép đặt chân.","detail":"Khu vực bị hỗn độn khí che phủ, bên trong có một đoạn cọc cây khô khổng lồ và những tia chớp đen không phát ra tiếng động. Nhiều truyền thuyết cho rằng đoạn cây liên quan đến một cao thủ bản thể cây hoặc tế linh mạnh nhất kỷ nguyên Tiên cổ.","theLucLienQuan":["Quân thủ thành Đế quan"],"nguon":["@c1360"]},{"id":"thanh-tho","name":"Thánh thổ","cn":"","capDo":"khac","parentId":"cuu-thien","blurb":"Nơi các đại tộc và đạo thống trên chín tầng trời tập trung đón những hậu bối thiên kiêu vừa đến.","detail":"Thánh thổ có kiến trúc liên miên, thần sơn với thác bạc, tiên hạc bay lượn và hà vụ bốc lên như tiên cảnh. Một tòa đồng điện cao ngàn trượng đặt tại đây, bên trong treo chuông lớn dùng để báo cho các tộc đến đón hậu bối.","theLucLienQuan":["Vương gia","Kim gia","Trường Sinh thế gia","Bổ Thiên Đạo","Tiệt Thiên Đạo"],"nguon":["@c1361"]},{"id":"de-thanh","name":"Đế Thành","cn":"","capDo":"thanh","parentId":"bien-hoang","blurb":"Tòa thành có quy củ nghiêm ngặt tại Biên Hoang, nơi nhiều thế lực công khai tranh cãi về danh dự Thạch Tộc.","detail":"Ba huynh đệ Thạch Tộc bị nhiều đại nhân vật bài xích tại đây. Quy củ trong thành khiến Vương Trường Hà và Cố Minh đạo không dám tùy tiện ra tay, còn thần uy từ Tổ đàn cuối cùng buộc những người phỉ báng phải nhận lỗi.","theLucLienQuan":["Thạch Tộc","Vương gia","Kim gia"],"nguon":["@c1362"]},{"id":"to-dan","name":"Tổ đàn","cn":"","capDo":"khac","parentId":"de-thanh","blurb":"Khu vực thần bí trong Đế Thành, chỉ có rất ít người được tiếp cận.","detail":"Những nhân vật được xưng là vô địch tọa quan tại đây. Khi Thạch Tộc bị phỉ báng, ba người phát thần uy trấn áp hiện trường rồi trải kim quang đại đạo nghênh đón nhóm Thạch Hạo.","theLucLienQuan":["Đế Thành","Thạch Tộc"],"nguon":["@c1362"]},{"id":"bien-hoang-de-quan","name":"Biên Hoang Đế quan","cn":"","capDo":"thanh","parentId":"bien-hoang","blurb":"Chiến địa tại Biên Hoang gắn với chuyện cũ của Thạch Tộc và sự hiện diện của đại quân Vương gia.","detail":"Vương gia đưa mười vạn tinh binh tới đây và năm nhân vật thuộc hàng Long bị đày trong hoàn cảnh khắc nghiệt. Những tranh luận về công tội của Thạch Tộc tại Biên Hoang cũng tập trung quanh khu vực này.","theLucLienQuan":["Thạch Tộc","Vương gia"],"nguon":["@c1362"]},{"id":"bo-lac-thach-toc-trong-de-thanh","name":"Bộ lạc Thạch Tộc trong Đế Thành","cn":"","aliases":[],"capDo":"khac","parentId":"de-thanh","blurb":"Nơi cư trú của hơn một nghìn hậu duệ Thạch Tộc bị quy thành Tội Huyết trong Đế Thành.","detail":"Bộ lạc nhỏ nằm giữa vùng núi rừng mang khí tức Mãng Hoang. Nơi đây có linh khí nghèo nàn, kém xa linh sơn của các đại tộc hàng đầu và chỉ còn hơn một nghìn cư dân mang họ Thạch.","theLucLienQuan":["Thạch Tộc tại Đế quan"],"nguon":["@c1364"]},{"id":"bo-lac-cua-tao-vu-sinh","name":"Bộ lạc của Tào Vũ Sinh","cn":"","aliases":[],"capDo":"khac","parentId":"de-thanh","blurb":"Bộ lạc cỡ trung được phân làm nơi cư trú của Tào Vũ Sinh.","detail":"Bộ lạc nằm đối diện nơi Thạch Hạo cư trú và chỉ cách bộ lạc Thạch Tộc một con sông.","theLucLienQuan":[],"nguon":["@c1364"]},{"id":"khu-vuc-ngoai-de-quan","name":"Khu vực ngoài Đế quan","cn":"","capDo":"vuc","parentId":"de-thanh","blurb":"Vùng đất ngoài Đế quan, nơi tồn tại tiên dược và những cơ duyên nghịch thiên liên quan tới việc sống thêm đời thứ hai.","detail":"Khu vực này chứa nhiều nguy hiểm chưa rõ và việc tìm kiếm tạo hóa cực kỳ khó khăn. Lão Thiên Nhân từng đề nghị điều Thạch Hạo tới đây tìm trường sinh tiên dược.","theLucLienQuan":["Cửu Thiên","Dị vực"],"nguon":["@c1366"]},{"id":"cam-khu-ngoai-de-quan","name":"Cấm khu ngoài Đế quan","cn":"","capDo":"khac","parentId":"khu-vuc-ngoai-de-quan","blurb":"Khu vực cấm nguy hiểm ngoài Đế quan, được Thạch Hạo suy đoán là nơi trường sinh tiên dược có thể sinh trưởng.","detail":"Người bình thường không thể tiếp cận nơi này và ngay cả Chí Tôn cũng có nguy cơ tử vong khi tiến vào.","theLucLienQuan":[],"nguon":["@c1366"]},{"id":"dien-vo-truong-tap-ket","name":"Diễn võ trường tập kết","cn":"","capDo":"khac","parentId":"de-thanh","blurb":"Diễn võ trường rộng lớn trong Đế quan, nơi cường giả các tộc tập hợp trước khi xuất quan tham chiến.","detail":"Thạch Hạo tới đây sau khi chấp nhận lệnh điều động. Một chấp pháp giả công khai nhắc mục tiêu giết mười vạn địch của hắn trước đám đông.","theLucLienQuan":["Cửu Thiên"],"nguon":["@c1366"]},{"id":"de-quan","name":"Đế quan","cn":"","capDo":"thanh","parentId":null,"blurb":"Cứ điểm nơi đại quân các tộc tập kết trước khi ra chiến trường. Thạch Tộc từng nắm quyền lớn tại đây nhưng nay đã suy tàn nghiêm trọng.","detail":"Đế quan là nơi Thạch Tộc từng có quyền bính lớn, song số người của bộ tộc hiện còn chưa đầy một nghìn. Khu vực này có diễn võ trường tập kết quân đội và tổ đàn nơi một sinh linh vô địch đang bế quan.","theLucLienQuan":["Đế Thành","Thạch Tộc","Kim gia"],"nguon":["@c1367"]},{"id":"quan-ngoai","name":"Quan ngoại","cn":"","capDo":"vuc","parentId":"de-quan","blurb":"Vùng chiến trường phía ngoài Đế quan, mở đầu bằng một đại sa mạc hoang lương chứa vô số hài cốt của cường giả hai giới.","detail":"Đại quân vượt giới môn để đặt chân tới quan ngoại. Nơi đây có tà dương đỏ máu, phong hỏa lâu đời, sông máu, huyết tuyền và nhiều hiểm họa gắn với cuộc chiến giữa hai giới.","theLucLienQuan":["Đại quân Đế quan"],"nguon":["@c1369"]},{"id":"dai-sa-mac-quan-ngoai","name":"Đại sa mạc quan ngoại","cn":"","capDo":"khac","parentId":"quan-ngoai","blurb":"Sa mạc mênh mông dưới tà dương đỏ máu, nơi đại quân đặt chân tới sau khi vượt khỏi Đế quan.","detail":"Sa mạc có phong hỏa lâu đời, huyết sắc trường hà, huyết tuyền và vô số xương khô nằm dưới cát. Hài cốt tại đây gồm cả Thần cốt còn khí tức cùng xương của những sinh linh trường sinh.","theLucLienQuan":["Đại quân Đế quan"],"nguon":["@c1369"]},{"id":"huyet-sac-truong-ha","name":"Huyết sắc trường hà","cn":"","capDo":"khac","parentId":"dai-sa-mac-quan-ngoai","blurb":"Dòng sông đỏ chảy xuyên qua đại sa mạc quan ngoại, chứa nhiều hài cốt kỳ dị của sinh linh tử trận.","detail":"Một đại kỵ sĩ giải thích đây là nhánh Hoàng Tuyền vốn có màu vàng nhưng đã bị máu của vô số cường giả nhuộm đỏ. Trong nước có cả xương của những sinh linh trường sinh.","theLucLienQuan":[],"nguon":["@c1369"]},{"id":"huyet-tuyen","name":"Huyết tuyền","cn":"","capDo":"khac","parentId":"dai-sa-mac-quan-ngoai","blurb":"Dòng suối máu trong đại sa mạc, nằm cách đoàn quân hơn mười dặm và là nơi Địa Ngục Chi Hoa xuất hiện.","detail":"Địa Ngục Chi Hoa mọc cạnh huyết tuyền khi còn chưa trưởng thành. Dòng suối sau đó khô cạn khi ma hoa độn xuống lòng đất và biến mất.","theLucLienQuan":[],"nguon":["@c1369"]},{"id":"dai-mac-bien-hoang","name":"Đại mạc Biên Hoang","cn":"","capDo":"khac","parentId":"bien-hoang","blurb":"Đại mạc mênh mông tại Biên Hoang, từng trải qua vô số cuộc chém giết.","detail":"Nơi quân Cửu Thiên Thập Địa và dị vực triển khai đội hình rồi bùng nổ đại chiến dưới Thiên Uyên. Trên chiến trường còn có các dấu vết và hài cốt do chiến tranh lâu đời để lại.","theLucLienQuan":["Cửu Thiên Thập Địa","Dị vực","Đế quan"],"nguon":["@c1370"]},{"id":"toa-thanh-co-bien-hoang","name":"Tòa thành cổ Biên Hoang","cn":"","capDo":"thanh","parentId":"bien-hoang","blurb":"Tòa thành thần bí từng trấn giữ Biên Hoang và đơn độc đối diện đại quân dị vực.","detail":"Tòa thành đã lâu không xuất hiện; một năm trước chỉ có người nghi thoáng nhìn thấy tàn ảnh. Tung tích hiện tại chưa rõ, có khả năng nó ẩn trong hư không hoặc đã bị phá hủy.","theLucLienQuan":["Thạch Tộc","Dị vực"],"nguon":["@c1370"]},{"id":"vom-troi-tren-chien-truong","name":"Vòm trời trên chiến trường","cn":"","capDo":"khac","parentId":"chien-truong","blurb":"Không gian cao phía trên chiến trường, ngoài tầm quan sát của người bình thường. Đây là nơi các cường giả cấp cao của Đế quan và dị vực giằng co bằng Tiên khí.","detail":"Mạnh Thiên Chính cùng hai lão giả phía Đế quan đối diện mười hai lão giả dị vực tại đây. Hai bên chưa giao thủ nhưng thế đối lập còn căng thẳng hơn những cuộc chém giết diễn ra bên dưới.","theLucLienQuan":["Cửu Thiên","Dị vực"],"nguon":["@c1374"]},{"id":"chien-truong-dai-mac-giua-hai-gioi","name":"Chiến trường đại mạc giữa hai giới","cn":"","capDo":"khac","parentId":"dai-mac-bien-hoang","blurb":"Chiến trường trong đại mạc nơi quân Cửu Thiên và Dị vực đối đầu. Nơi đây chứng kiến cuộc răn đe giữa hai Chí Tôn và trận giao phong giữa Thạch Hạo với Vũ Phong.","detail":"Hai đại quân tạm dừng giao tranh khi pháp chỉ được đưa ra, sau đó tiếp tục giằng co. Mạnh Thiên Chính và lão giả cầm Càn Khôn Đại ẩn vào bóng tối đối lập, còn Thạch Hạo đánh trọng thương Vũ Phong trước khi Dị vực triệt binh.","theLucLienQuan":["Cửu Thiên Thập Địa","Dị vực"],"nguon":["@c1376"]},{"id":"bich-lac-ho","name":"Bích Lạc hồ","cn":"","capDo":"khac","parentId":null,"blurb":"Hồ nước xanh biếc như ngọc, được chọn làm nơi tổ chức thiên tài thịnh hội.","detail":"Bích Lạc hồ nằm giữa quần sơn và tiên vụ, quanh năm tỏa khí tức Tiên đạo. Tương truyền thời cổ từng có Tiên cư trú tại khu vực này.","theLucLienQuan":[],"nguon":["@c1378"]},{"id":"quan-son-quanh-bich-lac-ho","name":"Quần sơn quanh Bích Lạc hồ","cn":"","capDo":"khac","parentId":"bich-lac-ho","blurb":"Khu quần sơn bao quanh Bích Lạc hồ, gồm nhiều linh sơn mang màu sắc và đạo vận khác nhau.","detail":"Các ngọn núi có nơi phát sáng, có nơi đen như mực hoặc mang màu tử kim. Không ít linh sơn lơ lửng giữa tiên vụ quanh hồ.","theLucLienQuan":[],"nguon":["@c1378"]},{"id":"vung-cam-tren-chin-tang-troi","name":"Vùng cấm trên chín tầng trời","cn":"","capDo":"vuc","parentId":null,"blurb":"Những khu vực thần bí và nguy hiểm trên chín tầng trời, lâu nay gần như không có sinh linh xuất thế.","detail":"Ban tổ chức thiên tài thịnh hội được đồn đã gửi thiệp mời vào một vùng cấm. Tin tức này gây chấn động tại Đế quan và khiến Thạch Hạo cùng Thiên Giác Nghĩ muốn tận mắt xem có sinh linh vùng cấm tới Bích Lạc hồ hay không.","theLucLienQuan":[],"nguon":["@c1378"]},{"id":"hon-dao-trong-bich-lac-ho","name":"Hòn đảo trong Bích Lạc hồ","cn":"","capDo":"khac","parentId":"bich-lac-ho","blurb":"Hòn đảo xanh biếc nổi lên giữa Bích Lạc hồ khi đại hội bắt đầu. Nơi đây được nghi là di chỉ Chân Tiên và tỏa ra Tiên Đạo khí tức.","detail":"Hòn đảo được màn ánh sáng bao bọc, bên trên còn cây cối và những dấu tích đổ nát. Sau khi nổi lên khỏi hồ, nơi này trở thành địa điểm chính để các thiên tài tụ hội.","theLucLienQuan":[],"nguon":["@c1380"]},{"id":"bich-lac-dao","name":"Bích Lạc Đảo","cn":"","capDo":"khac","parentId":"bich-lac-ho","blurb":"Hòn đảo tổ chức thịnh hội của thế hệ trẻ, nơi xung đột giữa Thạch Hạo và Kim gia bùng phát thành quyết đấu.","detail":"Các bên lo cuộc giao chiến sẽ phá hỏng nơi tụ hội nên quyết định chuyển trận đấu sang Bích Lạc đạo đài.","theLucLienQuan":["Kim gia","Vương gia","Vệ gia","Thác Cổ gia tộc"],"nguon":["@c1382","@c1399"]},{"id":"bich-lac-dao-dai","name":"Bích Lạc đạo đài","cn":"","capDo":"khac","parentId":"bich-lac-dao","blurb":"Đạo đài trên Bích Lạc Đảo được chọn làm nơi Thạch Hạo và Kim Chí Phi quyết chiến.","detail":"Đây là phần còn lại của một ngọn núi thông thiên bị chém đứt. Một Cổ Tiên từng quanh năm bế quan tại đây, khiến đạo đài trở nên thần thánh, kiên cố bất hủ và khó bị binh khí phá hủy.","theLucLienQuan":[],"nguon":["@c1382"]},{"id":"di-tich-chien-truong-tien-gia","name":"Di tích chiến trường Tiên gia","cn":"","capDo":"khac","parentId":null,"blurb":"Một di tích chiến trường cổ liên quan tới Tiên gia, nơi Hoàng Điệp từng gặp thi thể của một cổ Hoàng Điệp.","detail":"Hơn bốn năm trước, Hoàng Điệp gặp thi thể cổ Hoàng Điệp tại đây, hấp thu toàn bộ tinh khí còn sót lại rồi kết kén và tiếp tục tiến hóa đến hiện tại.","theLucLienQuan":[],"nguon":["@c1385"]},{"id":"thap-dia","name":"Thập Địa","cn":"","capDo":"gioi-dien","parentId":"cuu-thien-thap-dia","blurb":"Mười địa vực lớn thuộc Cửu Thiên Thập Địa, được thiên kiếp diễn hóa thành mười đại lục.","detail":"Trong thiên kiếp của Thạch Hạo, Thập Địa hiện thành mười đại lục rộng lớn, yên tĩnh và đẫm máu. Trên các đại lục có núi sông, vạn vật, thi hài, chiến kỳ cùng di tích của một chiến trường tận thế.","theLucLienQuan":["Cửu Thiên Thập Địa","Đại quân dị vực"],"nguon":["@c1386"]},{"id":"ba-ngan-chau","name":"Ba Ngàn Châu","cn":"","aliases":["Ba nghìn Đạo Châu"],"capDo":"vuc","parentId":"thap-dia","blurb":"Một địa vực thuộc Thập Địa, có hình dạng được nhận ra trong thiên kiếp của Thạch Hạo.","detail":"Một trong mười đại lục do thiên kiếp diễn hóa mang hình dạng giống Ba Ngàn Châu, nhưng có quy mô thu nhỏ hơn địa vực thật.","theLucLienQuan":[],"nguon":["@c1386"]},{"id":"khoi-ma","name":"Khởi Ma","cn":"","capDo":"vuc","parentId":"thap-dia","blurb":"Một địa vực ngang hàng với Ba Ngàn Châu trong Thập Địa.","detail":"Người quan sát nhận ra hình dạng Khởi Ma trong một đại lục do thiên kiếp của Thạch Hạo diễn hóa.","theLucLienQuan":[],"nguon":["@c1386"]},{"id":"loi-dien-phu-kieu","name":"Lôi Điện phù kiều","cn":"","capDo":"khac","parentId":"cuu-thien-thap-dia","blurb":"Những cây cầu bằng lôi điện nối các phần đại địa do Thiên Kiếp diễn hóa.","detail":"Lực lượng giam cầm khiến Thạch Hạo không thể trực tiếp bay lên Cửu Thiên. Hắn buộc phải đi qua các Lôi Điện phù kiều và lần lượt vượt từng vùng của Cửu Thiên Thập Địa.","theLucLienQuan":["Đại quân dị vực"],"nguon":["@c1387"]},{"id":"cau-noi","name":"Cầu nổi","cn":"","capDo":"khac","parentId":"cuu-thien-thap-dia","blurb":"Con đường nối chiến trường Thập Địa với Cửu Thiên trong lôi kiếp của Thạch Hạo.","detail":"Thạch Hạo vượt qua cầu nổi giữa sấm sét để rời chiến trường Thập Địa và tiến vào chiến trường Cửu Thiên nguy hiểm hơn.","theLucLienQuan":["Đại quân dị vực","Tiên dân Cửu Thiên Thập Địa"],"nguon":["@c1388"]},{"id":"thon-trang-trong-kiep-canh","name":"Thôn trang trong kiếp cảnh","cn":"","capDo":"khac","parentId":"cuu-thien","blurb":"Một thôn xóm hiện ra trong kiếp cảnh Cửu Thiên, nơi dân thường bị sinh linh dị vực tàn sát.","detail":"Thạch Hạo chứng kiến thiếu niên, thôn phụ, cô bé và ông lão trong thôn lần lượt bị sát hại. Hắn nổi giận giết tên đao phủ cùng hàng trăm sinh linh dị vực quanh khu vực này.","theLucLienQuan":["Đại quân dị vực","Tiên dân Cửu Thiên Thập Địa"],"nguon":["@c1388"]},{"id":"dai-hoang-trong-kiep-canh","name":"Đại Hoang trong kiếp cảnh","cn":"","capDo":"vuc","parentId":"cuu-thien","blurb":"Vùng hoang dã mà Thạch Hạo tiến vào trong kiếp cảnh sau khi rời các khu dân cư bị tàn sát.","detail":"Tại đây, Thạch Hạo bị hàng chục vạn rồi hơn triệu Ngân Sắc Ngô Công có cánh bao vây. Chúng phun sấm sét và nhiều lần xuyên thủng thân thể hắn, nhưng hắn vẫn giết thoát để tiến lên tầng trời cao hơn.","theLucLienQuan":[],"nguon":["@c1388"]},{"id":"tang-troi-thu-chin","name":"Tầng trời thứ chín","cn":"","aliases":["Tầng thứ chín"],"capDo":"vuc","parentId":"cuu-thien","blurb":"Tầng cao nhất Thạch Hạo tiến tới trong chặng lôi kiếp được tái hiện ở chương này.","detail":"Thạch Hạo kéo thân thể huyết nhục tan nát vượt liên tiếp các tầng sáu, bảy và tám rồi bước lên tầng trời thứ chín. Thành tựu này khiến những người quan chiến coi cuộc độ kiếp của hắn là một thần thoại chưa từng có.","theLucLienQuan":[],"nguon":["@c1388"]},{"id":"tang-tam","name":"Tầng tám","cn":"","capDo":"khac","parentId":null,"blurb":"Tầng thiên kiếp mà Thạch Hạo phải trả giá rất lớn mới vượt qua trước khi bước lên tầng cuối.","detail":"Sau khi vượt tầng tám, Thạch Hạo tiến vào tầng thứ chín với thân thể rách nát, xương thịt hư hao và một lỗ thủng lớn trước ngực.","theLucLienQuan":[],"nguon":["@c1389"]},{"id":"cuu-thien-chien-truong-noi-sau-xa-nhat","name":"Cửu Thiên chiến trường nơi sâu xa nhất","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực trung tâm của chiến trường trong tầng thiên kiếp cuối cùng.","detail":"Thạch Hạo giết xuyên nhiều lớp quân dị vực để tiến vào nơi này. Cuối chương, đại quân lùi ra và các kim quang đại đạo mang theo những sinh linh trẻ tuổi đáng sợ xuất hiện.","theLucLienQuan":["Cửu Thiên Thập Địa","Dị vực","Đế Tộc"],"nguon":["@c1389"]},{"id":"thien-kiep-o-ngoai","name":"Thiên kiếp ở ngoài","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực bên ngoài thiên kiếp, nơi những người quan sát theo dõi diễn biến tại tầng cuối.","detail":"Từ đây, các tu sĩ trẻ và những người chứng kiến bình luận về mức độ bất thường của kiếp nạn, khả năng lực lượng Bất Hủ xuất hiện và thân phận của nhóm sinh linh trẻ tuổi cuối chương.","theLucLienQuan":["Cửu Thiên Thập Địa","Tiên Viện"],"nguon":["@c1389"]},{"id":"co-tang-dia-di-vuc","name":"Cổ táng địa Dị Vực","cn":"","capDo":"khac","parentId":"the-gioi-di-vuc","blurb":"Khu chôn cất cổ xưa tại Dị Vực, không rõ thuộc về kỷ nguyên nào.","detail":"Những manh mối được khai quật tại đây từng khiến An Lan, Du Đà và các cường giả Dị Vực nghi ngờ phía trên lĩnh vực của họ vẫn còn một con đường, thậm chí có thể từng tồn tại sinh linh ở cấp độ cao hơn. Nguồn gốc của cổ táng địa và giả thuyết này đều chưa được xác thực.","theLucLienQuan":["Dị Vực","Đế tộc"],"nguon":["@c1390"]},{"id":"vung-bung-cua-thach-hao","name":"Vùng bụng của Thạch Hạo","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi tập trung dày đặc những cánh cửa trong cơ thể Thạch Hạo và được chọn làm khởi điểm để khai sáng con đường tu luyện mới.","detail":"Duy nhất động thiên nổ tung tại đây, mở hàng loạt cánh cửa phóng ra cả sinh cơ lẫn tử khí. Sau quá trình liên kết và tái tổ hợp, khu vực này biến đổi thành đổi phiên hải.","theLucLienQuan":[],"nguon":["@c1393"]},{"id":"cac-con-duong-lon-kim-quang","name":"Các con đường lớn kim quang","cn":"","capDo":"khac","parentId":null,"blurb":"Những con đường nơi các cao thủ Đế tộc đứng vây quanh Thạch Hạo.","detail":"Từ các con đường kim quang, những cao thủ Đế tộc đồng loạt vận dụng tổ thuật, pháp ấn và binh khí để phát động hợp kích.","theLucLienQuan":["Đế tộc"],"nguon":["@c1393"]},{"id":"thien-khung","name":"Thiên khung","cn":"","capDo":"khac","parentId":"thien","blurb":"Không gian phía trên chiến trường, nơi liên tiếp xuất hiện những dị tượng do con đường mới của Thạch Hạo dẫn phát.","detail":"Mưa máu, thi thể cổ, đại tinh, dấu ấn chân linh Tiên đạo, thần liên và thần kiều lần lượt hiện ra tại đây. Cuối chương, một vật mang tiên khí còn rơi xuống từ lôi quang trên thiên khung.","theLucLienQuan":[],"nguon":["@c1393"]},{"id":"luan-hai-cua-thach-hao","name":"Luân Hải của Thạch Hạo","cn":"","capDo":"khac","parentId":"vung-bung-cua-thach-hao","blurb":"Nơi sinh linh trên Đại đạo chi hoa tạm trú sau khi ba đạo Tiên khí của Thạch Hạo được tản vào thân thể.","detail":"Trong lúc Trảm Tiên đài phát lực diệt nguyên thần, sinh linh đạo quả từ Luân Hải lao vào đầu lâu Thạch Hạo và tạm hợp nhất với nguyên thần để chết thay hắn.","theLucLienQuan":[],"nguon":["@c1395"]},{"id":"bat-diet-son","name":"Bất diệt sơn","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Thạch Hạo từng trải qua huyết chiến trong hành trình đi lấy Bất Diệt Kinh.","detail":"Thạch Hạo có được Luân Hồi ấn thứ năm sau cuộc huyết chiến gắn với hành trình lấy Bất Diệt Kinh tại đây.","theLucLienQuan":[],"nguon":["@c1395"]},{"id":"tang-troi-thu-muoi","name":"Tầng trời thứ mười","cn":"","capDo":"gioi-nho","parentId":"thien-khung","blurb":"Tầng trời mờ ảo nằm phía trên chín tầng lôi kiếp. Nơi đây có một Lôi Trì nhỏ chứa hỗn độn và tiên khí.","detail":"Tầng trời thứ mười khó nhìn thấu ngay cả khi Thạch Hạo mở thiên nhãn. Lôi Trì tại đây nhỏ hơn phó trì ở tầng thứ chín nhưng chứa hỗn độn cùng tiên khí, được hắn nhận định là nguồn tạo hóa cao hơn và có thể là nơi lôi kiếp dịch nhỏ xuống tầng dưới.","theLucLienQuan":[],"nguon":["@c1396"]},{"id":"bi-gioi-bi-phong-an-thuoc-ky-nguyen-truoc","name":"Bí giới bị phong ấn thuộc kỷ nguyên trước","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Một bí giới cổ bị phong ấn, tràn ngập lôi quang và chớp giật. Vương Đại từng suýt chết tại đây.","detail":"Vương Đại từng tiến vào bí giới này và gặp nguy hiểm giữa lôi điện vô tận, khiến Vương Trường Sinh phải mang Trường Sinh chiến kích tới cứu. Vương Hi thúc tổ nghi ngờ Lôi Linh có thể liên quan đến nơi đây, nhưng nguồn gốc đó chưa được xác nhận.","theLucLienQuan":["Vương gia"],"nguon":["@c1396"]},{"id":"loi-hai","name":"Lôi hải","cn":"","capDo":"khac","parentId":"khu-vuc-thien-kiep","blurb":"Khu vực thiên kiếp dày đặc hồ quang và tiếng sét, bao quanh Lôi Trì.","detail":"Lôi hải tràn ngập ánh chớp chói mắt và tiếng sét điếc tai, khiến phần lớn người quan sát khó nhìn rõ cuộc tranh đấu giữa Thạch Hạo và các Lôi Linh quanh Lôi Trì.","theLucLienQuan":[],"nguon":["@c1397"]},{"id":"tang-troi-thu-chin-cua-loi-kiep","name":"Tầng trời thứ chín của lôi kiếp","cn":"","capDo":"khac","parentId":"loi-hai","blurb":"Tầng lôi kiếp có Lôi Trì từng cung cấp lôi kiếp dịch cho Thạch Hạo.","detail":"Sau khi xử lý ba Lôi Linh, Thạch Hạo trở lại Lôi Trì và luyện hóa sạch phần lôi kiếp dịch còn lại trước khi tiến lên tầng trời thứ mười.","theLucLienQuan":[],"nguon":["@c1399"]},{"id":"tang-troi-thu-muoi-cua-loi-kiep","name":"Tầng trời thứ mười của lôi kiếp","cn":"","capDo":"khac","parentId":"loi-hai","blurb":"Tầng cuối của lôi kiếp, nơi tồn tại Lôi Trì chân chính chứa tạo hóa chung cực.","detail":"Không gian ban đầu tràn ngập thần quang an lành nhưng lập tức hóa thành lôi đình dữ dội khi Thạch Hạo xâm nhập. Tại đây có một Lôi Trì bằng cổ nham thạch chứa chất lỏng đỏ óng mang sức mạnh bàng bạc.","theLucLienQuan":[],"nguon":["@c1399"]},{"id":"khe-nut-hoi-tu-thien-kiep","name":"Khe nứt hội tụ thiên kiếp","cn":"","capDo":"khac","parentId":"thien-khung","blurb":"Những khe nứt kỳ dị trên vòm trời thu nạp lôi quang khi thiên kiếp sắp kết thúc.","detail":"Các khe nứt hút lôi quang về một vị trí bí ẩn và gần kéo Thạch Hạo đi theo Lôi Trì. Chúng khép lại khi thời gian thiên kiếp kết thúc, cắt đứt phần lớn lôi đình ở bên ngoài.","theLucLienQuan":[],"nguon":["@c1400"]}]};
